/**
 * Message catalogue for the menu-bar popover. Generated by `pnpm i18n:build`
 * from the keys that window's module graph can reach.
 */
import { createLazyAppI18n } from './create';

const { instance, ready } = createLazyAppI18n({
  en: () => import('./tray.en.json'),
  de: () => import('./tray.de.json'),
});
export const trayI18n = instance;
export const trayI18nReady = ready;
